  1092  /*
  1093   * Read a COOLKEY coolkey object.
  1094   */
  1095  static int coolkey_read_object(sc_card_t *card, unsigned long object_id, size_t offset,
  1096                          u8 *out_buf, size_t out_len, u8 *nonce, size_t nonce_size)
  1097  {
  1098          coolkey_read_object_param_t params;
  1099          u8 *out_ptr;
  1100          size_t left = 0;
  1101          size_t len;
  1102          int r;
  1103
  1104          ulong2bebytes(&params.object_id[0], object_id);
  1105
  1106          out_ptr = out_buf;
  1107          left = out_len;
  1108          do {
  1109                  ulong2bebytes(&params.offset[0], offset);
  1110                  params.length = MIN(left, COOLKEY_MAX_CHUNK_SIZE);
  1111                  len = left;
  1112                  r = coolkey_apdu_io(card, COOLKEY_CLASS, COOLKEY_INS_READ_OBJECT, 0, 0,
  1113                          (u8 *)&params, sizeof(params), &out_ptr, &len, nonce, nonce_size);
  1114                  if (r < 0) {
  1115                          goto fail;
  1116                  }
  1117                  /* sanity check to make sure we don't overflow left */
  1118                  if ((left < len) || (len == 0)) {
  1119                          r = SC_ERROR_INTERNAL;
  1120                          goto fail;
  1121                  }
  1122                  out_ptr += len;
  1123                  offset += len;
  1124                  left -= len;
  1125          } while (left != 0);
  1126
  1127          return out_len;
  1128
  1129  fail:
  1130          return r;
  1131  }
