  1372          }
  1373          new_obj_data = malloc(buf_len);
  1374          if (new_obj_data == NULL) {
  1375                  return SC_ERROR_OUT_OF_MEMORY;
  1376          }
  1377          r = coolkey_read_object(card, obj->id, 0, new_obj_data, buf_len,
  1378                                  priv->nonce, sizeof(priv->nonce));
  1379          if (r != (int)buf_len) {
  1380                  free(new_obj_data);
  1381                  return SC_ERROR_CORRUPTED_DATA;
  1382          }
  1383          obj_entry = coolkey_find_object_by_id(&priv->objects_list, obj->id);
  1384          if (obj_entry == NULL) {
  1385                  free(new_obj_data);
  1386                  return SC_ERROR_INTERNAL; /* shouldn't happen */
  1387          }
  1388          if (obj_entry->data != NULL) {
  1389                  free(new_obj_data);
  1390                  return SC_ERROR_INTERNAL; /* shouldn't happen */
  1391          }
  1392          /* Make sure we will not go over the allocated limits in the other
  1393           * objects if they somehow got different lengths in matching objects */
  1394          if (obj_entry->length != obj->length) {
  1395                  free(new_obj_data);
  1396                  return SC_ERROR_INTERNAL; /* shouldn't happen */
  1397          }
  1398          obj_entry->data = new_obj_data;
  1399          obj->data = new_obj_data;
  1400          return SC_SUCCESS;
  1400          return SC_SUCCESS;
  1401  }
