  1403  /*
  1404   * return a parsed record for the attribute which includes value, type, and length.
  1405   * Handled both v1 and v0 record types. determine record type from the object.
  1406   *  make sure we don't overrun the buffer if the token gives us bad data.
  1407   */
  1408  static int
  1409  coolkey_find_attribute(sc_card_t *card, sc_cardctl_coolkey_attribute_t *attribute)
  1410  {
  1411          u8 object_record_type;
  1412          CK_ATTRIBUTE_TYPE attr_type = attribute->attribute_type;
  1413          const u8 *obj = attribute->object->data;
  1414          const u8 *attr = NULL;
  1415          size_t buf_len = attribute->object->length;
  1416          coolkey_object_header_t *object_head;
  1417          int attribute_count,i;
  1418          attribute->attribute_data_type = SC_CARDCTL_COOLKEY_ATTR_TYPE_STRING;
  1419          attribute->attribute_length = 0;
  1420          attribute->attribute_value = NULL;
  1421
  1422          if (obj == NULL) {
  1423                  /* cast away const so we can cache the data value */
  1424                  int r = coolkey_fill_object(card, (sc_cardctl_coolkey_object_t *)attribute->object);
  1425                  if (r < 0) {
  1426                          return r;
  1427                  }
  1428                  obj = attribute->object->data;
  1429                  if (obj == NULL) {
  1430                          return SC_ERROR_INTERNAL;
  1431                  }
  1432          }
  1433
  1434          /* should be a static assert so we catch this at compile time */
  1435          assert(sizeof(coolkey_object_header_t) >= sizeof(coolkey_v0_object_header_t));
  1436          /* make sure we have enough of the object to read the record_type */
  1437          if (buf_len <= sizeof(coolkey_v0_object_header_t)) {
  1438                  return SC_ERROR_CORRUPTED_DATA;
  1439          }
  1440          object_head = (coolkey_object_header_t *)obj;
  1441          object_record_type = object_head->record_type;
  1442          /* make sure it's a type we recognize */
  1443          if ((object_record_type != COOLKEY_V1_OBJECT) && (object_record_type != COOLKEY_V0_OBJECT)) {
  1444                  return SC_ERROR_CORRUPTED_DATA;
  1445          }
  1446
  1447
  1448          /*
  1449           * now loop through all the attributes in the list. first find the start of the list
  1450           */
  1451          attr = coolkey_attribute_start(obj, object_record_type, buf_len);
  1452          if (attr == NULL) {
  1453                  return SC_ERROR_CORRUPTED_DATA;
  1454          }
  1455          buf_len -= (attr-obj);
  1456
  1457          /* now get the count */
  1458          attribute_count = coolkey_get_attribute_count(obj, object_record_type, buf_len);
  1459          for (i=0; i < attribute_count; i++) {
  1460                  size_t record_len = coolkey_get_attribute_record_len(attr, object_record_type, buf_len);
  1461                  /* make sure we have the complete record */
  1462                  if (buf_len < record_len || record_len < 4) {
  1463                                  return SC_ERROR_CORRUPTED_DATA;
  1464                  }
  1465                  /* does the attribute match the one we are looking for */
  1466                  if (attr_type == coolkey_get_attribute_type(attr, object_record_type, record_len)) {
  1467                          /* yup, return it */
  1468                          return coolkey_get_attribute_data(attr, object_record_type, record_len, attribute);
  1469                  }
  1470                  /* go to the next attribute on the list */
  1471                  buf_len -= record_len;
  1472                  attr += record_len;
  1473          }
  1474          /* not find in attribute list, check the fixed attribute record */
  1475          if (object_record_type == COOLKEY_V1_OBJECT) {
  1476                  unsigned long fixed_attributes = bebytes2ulong(object_head->fixed_attributes_values);
  1477
  1478                  return coolkey_get_attribute_data_fixed(attr_type, fixed_attributes, attribute);
  1479          }
  1480          return SC_ERROR_DATA_OBJECT_NOT_FOUND;
  1481  }
